srcDoc.css:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap');
* { box-sizing: border-box; }

/* budgetplaner design tokens */
:root { --accent: #C84182; --accent-light: #FCEAF2; --accent-dark: #A83670; }

.app {
  min-height: calc(var(--appsmith-ui-height) * 1px);
  width: calc(var(--appsmith-ui-width) * 1px);
  border-radius: var(--appsmith-theme-borderRadius);
  box-shadow: var(--appsmith-theme-boxShadow);
  padding: 20px 22px;
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, system-ui, sans-serif;
  background: #ffffff;
  color: #1b1f27;
  font-size: 13px;
}

.header { margin-bottom: 14px; }
.header h1 { font-size: 18px; font-weight: 700; margin: 0 0 2px; letter-spacing: -0.01em; }
.header .sub { color: #6b7280; font-size: 12px; }

/* Tabs */
.tabs { display: flex; gap: 4px; border-bottom: 1px solid #e6e8ec; margin-bottom: 16px; }
.tab {
  padding: 8px 14px; cursor: pointer; font-weight: 600; font-size: 13px;
  color: #6b7280; border-bottom: 2px solid transparent; margin-bottom: -1px; user-select: none;
}
.tab:hover { color: #1b1f27; }
.tab.active { color: var(--appsmith-theme-primaryColor, #C84182); border-bottom-color: var(--appsmith-theme-primaryColor, #C84182); }

/* KPI cards */
.kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; margin-bottom: 16px; }
.kpi-grp { font-size: 10.5px; font-weight: 700; text-transform: uppercase; letter-spacing: .05em; color: #8a94a6; margin: 2px 2px 9px; display: flex; align-items: center; gap: 7px; }
.kpi-grp::before { content: ""; flex: none; width: 3px; height: 13px; border-radius: 2px; background: #cbd0d8; }
.kpi { border: 1px solid #e6e8ec; border-radius: 10px; padding: 12px 14px; background: #fbfbfd; }
.kpi .k-label { font-size: 10.5px; color: #6b7280; text-transform: uppercase; letter-spacing: 0.02em; font-weight: 600; display:flex; align-items:center; flex-wrap:wrap; gap:4px 6px; min-width:0; overflow-wrap:break-word; }
.kpi .k-value { font-size: 24px; font-weight: 700; margin-top: 4px; line-height: 1.1; }
.kpi .k-sub { font-size: 11px; color: #8a94a6; margin-top: 2px; }
.kpi.total { background: #FCEAF2; border-color: #f3d9e8; }
.kpi.conv { background: #eef7f0; border-color: #cfe8d6; }
.kpi.clickable-kpi { cursor: pointer; transition: box-shadow 0.15s, border-color 0.15s; }
.kpi.clickable-kpi:hover { border-color: var(--appsmith-theme-primaryColor, #C84182); box-shadow: 0 2px 8px rgba(200,65,130,0.12); }
.kpi .zoom { font-size: 10px; color: var(--appsmith-theme-primaryColor, #C84182); font-weight: 700; margin-left: 4px; }
.dot { width: 9px; height: 9px; border-radius: 50%; display: inline-block; }
.mini-badge { font-size: 9px; font-weight: 700; color: #1f9d55; background: #e7f5ec; border-radius: 10px; padding: 1px 6px; margin-left: 4px; vertical-align: middle; }
.hp-badge { font-size: 10px; font-weight: 700; color: #b4361e; background: #fdeee9; border: 1px solid #f6d3c7; border-radius: 20px; padding: 1px 8px; margin-left: 8px; white-space: nowrap; }
.controls-left { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }

/* Controls */
.controls { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 10px; flex-wrap: wrap; }
.seg-toggle { display: inline-flex; background: #f1f2f5; border-radius: 8px; padding: 3px; }
.seg-toggle button {
  border: none; background: none; padding: 6px 12px; border-radius: 6px; cursor: pointer;
  font-weight: 600; font-size: 12px; color: #6b7280;
}
.seg-toggle button.active { background: #fff; color: #1b1f27; box-shadow: 0 1px 2px rgba(0,0,0,0.08); }
.search { position: relative; }
.search input {
  border: 1px solid #e0e2e8; border-radius: 8px; padding: 7px 10px 7px 30px; font-size: 12px;
  width: 240px; outline: none; background: #fff;
}
.search input:focus { border-color: var(--appsmith-theme-primaryColor, #C84182); }
.search .ico { position: absolute; left: 10px; top: 50%; transform: translateY(-50%); color: #9aa0ac; font-size: 13px; }

/* Table / tree */
.tree { border: 1px solid #e6e8ec; border-radius: 10px; overflow: hidden; }
.thead, .row { display: grid; grid-template-columns: minmax(175px, 1.7fr) 50px 1fr 112px; align-items: center; }
.thead {
  background: #f7f8fa; border-bottom: 1px solid #e6e8ec; font-size: 11px; text-transform: uppercase;
  letter-spacing: 0.03em; color: #8a94a6; font-weight: 700; padding: 9px 14px;
}
.thead .num, .row .num { text-align: right; }
.row { padding: 8px 14px; border-bottom: 1px solid #f0f1f4; cursor: default; }
.row:last-child { border-bottom: none; }
.row.clickable { cursor: pointer; }
.row.clickable:hover { background: #fafbfc; }
.row.lvl0 { font-weight: 650; }
.row.lvl1 { background: #fcfcfd; }
.row.lvl2 { background: #fafbfc; }
.row.leaf { background: #f7f8fa; }
.name-cell { display: flex; align-items: center; gap: 7px; min-width: 0; }
.caret { width: 14px; text-align: center; color: #9aa0ac; font-size: 10px; transition: transform 0.12s; flex: none; }
.caret.open { transform: rotate(90deg); }
.name-txt { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.count-big { font-variant-numeric: tabular-nums; font-weight: 600; }
.mig-pct { text-align: right; font-variant-numeric: tabular-nums; font-weight: 600; }

/* stacked bar */
.bar { display: flex; height: 8px; width: 104px; flex: none; border-radius: 4px; overflow: hidden; background: #eef0f3; }
.bar span { display: block; height: 100%; }
.bar-wrap { display: flex; align-items: center; gap: 10px; }
.bar-legend { font-size: 11px; color: #8a94a6; font-variant-numeric: tabular-nums; white-space: nowrap; }

/* account leaf badges */
.acct { display: flex; align-items: center; gap: 8px; padding: 5px 14px 5px 44px; border-bottom: 1px solid #f0f1f4; font-size: 12px; }
.acct:last-child { border-bottom: none; }
.badge { font-size: 10px; font-weight: 700; padding: 2px 7px; border-radius: 20px; color: #fff; white-space: nowrap; }
.acct-book { margin-left: auto; font-size: 11px; color: #8a94a6; font-variant-numeric: tabular-nums; white-space: nowrap; padding-left: 10px; }

/* opportunity leaf rows */
.opp-row { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 12px; padding: 7px 14px; border-bottom: 1px solid #f0f1f4; }
.opp-row:last-child { border-bottom: none; }
.opp-row:hover { background: #fafbfc; }
.opp-left { display: flex; align-items: flex-start; gap: 8px; min-width: 0; }
.opp-txt { min-width: 0; }
.opp-acct { font-weight: 600; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.opp-meta { font-size: 11px; color: #8a94a6; margin-top: 1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.opp-amt { font-variant-numeric: tabular-nums; font-weight: 600; font-size: 12.5px; white-space: nowrap; }
.opp-row .badge { margin-top: 1px; }

/* week-over-week table */
.wow-row { display: grid; grid-template-columns: minmax(180px, 2fr) 110px 110px 70px 1fr; align-items: center; padding: 9px 14px; border-bottom: 1px solid #f0f1f4; }
.wow-row .num { text-align: right; font-variant-numeric: tabular-nums; }
.wow-head { background: #f7f8fa; border-bottom: 1px solid #e6e8ec; font-size: 11px; text-transform: uppercase; letter-spacing: 0.03em; color: #8a94a6; font-weight: 700; }
.wow-delta { font-weight: 700; }
.wow-delta.pos { color: #1f9d55; }
.wow-delta.neg { color: #e5484d; }
.wow-delta.zero { color: #b8bdc7; }
.wow-bar { height: 9px; width: 100%; max-width: 220px; background: #eef0f3; border-radius: 4px; overflow: hidden; margin-left: 10px; }
.wow-bar span { display: block; height: 100%; }
.wow-total { font-weight: 700; background: #fafbfc; border-top: 2px solid #e6e8ec; border-bottom: none; }
.wow-note { font-size: 11px; color: #8a94a6; padding: 12px 14px 2px; line-height: 1.5; }

/* flow (movement) table */
.flow-row { display: grid; grid-template-columns: minmax(160px, 2fr) 104px 92px 92px 78px 104px; align-items: center; padding: 8px 14px; border-bottom: 1px solid #f0f1f4; }
.flow-row .num { text-align: right; font-variant-numeric: tabular-nums; }
.flow-head { background: #f7f8fa; border-bottom: 1px solid #e6e8ec; font-size: 11px; text-transform: uppercase; letter-spacing: 0.03em; color: #8a94a6; font-weight: 700; }
.flow-in { color: #1f9d55; font-weight: 600; }
.flow-out { color: #e5484d; font-weight: 600; }
.flow-new { color: #3b82f6; font-weight: 600; }
.flow-total { font-weight: 700; background: #fafbfc; border-top: 2px solid #e6e8ec; }
.flow-row.clickable { cursor: pointer; }
.flow-row.clickable:hover { background: #fafbfc; }

/* week-over-week stage drill-down (which accounts moved) */
.wow-detail { background: #fafbfc; border-bottom: 1px solid #f0f1f4; padding: 4px 14px 10px 34px; }
.wow-dgrp { font-size: 10px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.03em; margin: 9px 0 3px; }
.wow-dgrp.flow-in { color: #1f9d55; }
.wow-dgrp.flow-out { color: #e5484d; }
.wow-dgrp.flow-new { color: #3b82f6; }
.wow-drow { display: grid; grid-template-columns: minmax(130px, 1.7fr) minmax(90px, auto) 92px; align-items: baseline; gap: 10px; padding: 3px 0; font-size: 12px; border-bottom: 1px solid #f2f3f5; }
.wow-drow:last-child { border-bottom: none; }
.wd-acct { font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wd-move { font-size: 11px; color: #8a94a6; white-space: nowrap; }
.wd-amt { text-align: right; font-variant-numeric: tabular-nums; color: #4b5563; }

/* multi-week trend chart */
.trend-title { font-size: 12px; font-weight: 600; color: #1b1f27; margin: 2px 0 8px; }
.rev-trend-hdr { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 4px; }
.rev-trend-hdr .trend-title { margin: 2px 0; }
.trend-wrap { border: 1px solid #e6e8ec; border-radius: 10px; padding: 8px 6px 2px; background: #fff; }
.trend-legend { display: flex; flex-wrap: wrap; gap: 10px 14px; margin: 10px 2px 16px; font-size: 11px; color: #4b5563; }
.trend-leg-item { display: inline-flex; align-items: center; gap: 5px; }
.trend-sw { width: 10px; height: 10px; border-radius: 2px; display: inline-block; }
.trend-note { font-size: 10.5px; color: #9aa0ac; padding: 0 2px 14px; line-height: 1.5; }

/* revenue block (Neues Offering) — budgetplaner magenta accent */
.rev-block { border: 1px solid #f3d9e8; background: #fdf7fb; border-radius: 12px; padding: 14px 14px 8px; margin-bottom: 18px; }
.rev-title { font-size: 13px; font-weight: 700; color: var(--accent-dark); margin: 2px 0 12px; }
.rev-title span { font-weight: 500; color: #8a94a6; font-size: 11px; }
.rev-row { display: grid; grid-template-columns: minmax(150px, 1.6fr) 1fr 1fr; align-items: center; padding: 8px 12px; border-bottom: 1px solid #f0f1f4; }
.rev-row:last-child { border-bottom: none; }
.rev-row .num { text-align: right; font-variant-numeric: tabular-nums; font-weight: 600; }
.rev-head { background: #f7f8fa; font-size: 10.5px; text-transform: uppercase; letter-spacing: 0.03em; color: #8a94a6; }
.rev-head .num { font-weight: 700; }
.rev-sub { color: #9aa0ac; font-weight: 400; font-size: 11px; }

/* loss reasons drill-down */
.loss-row { display: grid; grid-template-columns: minmax(220px, 2.6fr) 90px 120px; align-items: center; padding: 9px 14px; border-bottom: 1px solid #f0f1f4; }
.loss-row .num { text-align: right; font-variant-numeric: tabular-nums; }
.loss-head { background: #f7f8fa; border-bottom: 1px solid #e6e8ec; font-size: 11px; text-transform: uppercase; letter-spacing: 0.03em; color: #8a94a6; font-weight: 700; }
.loss-row.cat { font-weight: 650; cursor: pointer; }
.loss-row.cat:hover { background: #fafbfc; }
.loss-row.reason { background: #fcfcfd; cursor: pointer; }
.loss-row.reason:hover { background: #f7f8fa; }
.loss-deal { padding: 8px 14px 8px 50px; border-bottom: 1px solid #f0f1f4; }
.loss-deal:last-child { border-bottom: none; }
.loss-deal .ld-top { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }
.loss-deal .ld-acct { font-weight: 600; font-size: 12.5px; }
.loss-deal .ld-detail { color: #8a94a6; font-size: 11px; margin-top: 3px; font-style: italic; line-height: 1.45; }

/* empty / placeholder */
.empty, .placeholder { text-align: center; padding: 40px 24px; color: #6b7280; }
.empty h3, .placeholder h3 { color: #1b1f27; font-size: 15px; margin: 0 0 8px; }
.empty code { background: #f1f2f5; padding: 1px 6px; border-radius: 4px; font-size: 12px; }
.empty ol { text-align: left; max-width: 460px; margin: 14px auto 0; line-height: 1.7; font-size: 12px; }
.pill { display:inline-block; background:#FCEAF2; color:#C84182; border-radius:20px; padding:3px 10px; font-size:11px; font-weight:600; margin-bottom:10px; }

/* WIP claim — Success tab is a preview while tracking is refined */
.tab-wip { font-size:8.5px; font-weight:800; text-transform:uppercase; letter-spacing:.03em; color:#fff; background:#e0a800; border-radius:9px; padding:1px 5px; margin-left:4px; vertical-align:middle; position:relative; top:-1px; }
.wip-banner { display:flex; align-items:center; gap:12px; border:1px solid #ffd9a8; background:#fff8ec; border-radius:11px; padding:11px 15px; margin-bottom:18px; flex-wrap:wrap; }
.wip-banner .wip-tag { flex:none; font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:.03em; color:#a85a00; background:#ffedcc; border-radius:20px; padding:4px 11px; white-space:nowrap; }
.wip-banner .wip-txt { font-size:12px; color:#6b5a3a; line-height:1.5; flex:1; min-width:220px; }

/* section header on operational tabs (reuses .tier-head) */
.sec-head { margin-top: 4px; }

/* success / north-star tab */
.succ-hdr { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 14px; flex-wrap: wrap; }
.succ-title { font-size: 15px; font-weight: 700; color: #1b1f27; }
.succ-sub { font-size: 11.5px; color: #8a94a6; margin-top: 3px; max-width: 620px; line-height: 1.5; }
.motion-wrap { display: inline-flex; align-items: center; gap: 8px; }
.motion-lbl { font-size: 10.5px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; color: #8a94a6; }
.motion-select { font: inherit; font-size: 12.5px; padding: 6px 10px; border: 1px solid #d8dbe2; border-radius: 8px; background: #fff; color: #1b1f27; cursor: pointer; }
.motion-select:focus { outline: none; border-color: var(--appsmith-theme-primaryColor, #C84182); }

.ns-hero { border: 1px solid #cfe9d9; background: linear-gradient(180deg,#f2fbf5,#fbfffc); border-radius: 12px; padding: 16px 18px; margin-bottom: 20px; }
.ns-h-label { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: #1f9d55; }
.ns-h-value { font-size: 32px; font-weight: 800; line-height: 1.05; margin-top: 4px; color: #14663a; }
.ns-h-sub { font-size: 12.5px; color: #3d4551; margin-top: 8px; }
.ns-h-sub em { font-style: normal; color: #8a94a6; font-size: 11px; }
.ns-h-note { font-size: 11px; color: #9aa0ac; margin-top: 8px; font-style: italic; }

.tier { margin-bottom: 20px; }
.tier-head { display: flex; align-items: center; gap: 8px; margin: 0 2px 10px; font-size: 12.5px; font-weight: 700; color: #1b1f27; }
.tier-num { background: var(--accent-light); color: var(--accent); border-radius: 7px; padding: 2px 9px; font-size: 12px; font-weight: 900; }
.tier-head span:nth-child(2) { text-transform: uppercase; letter-spacing: .04em; font-weight: 800; }
.tier-sub { font-weight: 500; color: #8a94a6; font-size: 11px; }
.base-line { display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: 11px; color: #8a94a6; margin-top: 4px; }
.ns-pill { font-weight: 700; border-radius: 6px; padding: 1px 6px; font-size: 10.5px; white-space: nowrap; }
.ns-pill.up { color: #1f9d55; background: #e7f6ec; }
.ns-pill.down { color: #c2410c; background: #fdeee2; }
.ns-na { color: #c0c5cf; }
.kpi.v15 { opacity: 0.55; background: #f6f7f9; border-style: dashed; }

/* stronger new-vs-existing colour separation on the guardrail cards */
.kpi.neu  { background: #fff8ee; border-color: #f6dcae; border-left: 3px solid #f59e0b; }
.kpi.best { background: #eff5fe; border-color: #cfe0fa; border-left: 3px solid #3b82f6; }

/* Demo -> Pilot -> Account funnel card — spans the full KPI row so the
   horizontal funnel always has room; overflow-x is a safety net for very narrow widgets. */
.kpi.funnel-card { grid-column: 1 / -1; }
.funnel-card .funnel { display: flex; align-items: stretch; gap: 6px; margin-top: 6px; min-width: 0; overflow-x: auto; max-width: 520px; }
.fn-stage { flex: 1 1 0; min-width: 0; text-align: center; background: #fff4e5; border: 1px solid #f6dcae; border-radius: 8px; padding: 8px 2px; }
.fn-n { font-size: 19px; font-weight: 800; line-height: 1; color: #b45309; }
.fn-l { font-size: 9px; color: #6b7280; text-transform: uppercase; letter-spacing: 0.02em; margin-top: 3px; white-space: nowrap; }
.fn-arr { flex: 0 0 auto; display: flex; flex-direction: column; align-items: center; justify-content: center; min-width: 20px; }
.fn-arr span { color: #b8c0cf; font-size: 9px; line-height: 1; }
.fn-cr { font-size: 10.5px; font-weight: 700; color: #d97706; margin-top: 2px; }

/* definition call-out (Success tab) */
.def-callout { border: 1px solid #ffe2a8; background: #fffaf0; border-radius: 10px; padding: 10px 14px; margin-bottom: 18px; font-size: 12px; line-height: 1.55; color: #5b4a2a; }
.def-callout strong { color: #8a5a00; }
.def-callout b { color: #1b1f27; font-weight: 650; }
.def-callout code { background: #f4ece0; padding: 1px 5px; border-radius: 4px; font-size: 11px; }

/* funnel baseline comparison line */
.fn-base { font-size: 10.5px; color: #8a94a6; margin-top: 7px; line-height: 1.5; }
.fn-base b { color: #3d4551; font-weight: 650; }
.fn-base span { color: #b0b6c0; }

/* Account View: qualified migration-rate (secondary) */
.mig-qual { color: #8a94a6; font-weight: 600; }
.mig-pct { display: flex; flex-direction: column; align-items: flex-end; gap: 2px; line-height: 1.35; }
.mig-ln { white-space: nowrap; }
.mig-ln .mig-k { color: #b0b6c0; font-weight: 800; font-size: 9px; text-transform: uppercase; letter-spacing: .02em; margin-right: 3px; }
.mig-eur { font-size: 11px; opacity: .9; }
.mig-head { display: flex; flex-direction: column; align-items: flex-end; gap: 1px; }
.ret-detail { border:1px solid #e6e8ec; border-radius:10px; margin-top:10px; overflow:hidden; }
.ret-row { display:grid; grid-template-columns: minmax(150px,2fr) 1fr 1fr 66px; align-items:center; padding:7px 14px; border-bottom:1px solid #f0f1f4; font-size:12px; }
.ret-row:last-child { border-bottom:none; }
.ret-row .num { text-align:right; font-variant-numeric:tabular-nums; }
.ret-head { background:#f7f8fa; font-size:10.5px; text-transform:uppercase; letter-spacing:.03em; color:#8a94a6; font-weight:700; }
.ret-acct { display:flex; flex-direction:column; min-width:0; }
.ret-acct > span:first-child { white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.ret-win { font-size:10px; color:#a6adb8; font-variant-numeric:tabular-nums; margin-top:1px; }
.ret-badge { display:inline-block; font-size:9px; font-weight:700; padding:0 5px; border-radius:6px; margin-right:5px; vertical-align:middle; letter-spacing:.02em; }
.ret-badge.ext { background:#fef3c7; color:#b45309; }
.ret-badge.reakt { background:#e5e7eb; color:#4b5563; }
.ret-nb .ret-win { color:#b8bdc7; }
.ret-up { border-left:3px solid #1f9d55; }
.ret-down { border-left:3px solid #f59e0b; }
.ret-nb { border-left:3px solid #cbd0d8; color:#8a94a6; }
.pnn-cap { padding:9px 14px; font-size:11px; color:#8a94a6; background:#fafbfc; border-bottom:1px solid #f0f1f4; }
.pnn-row { display:grid; grid-template-columns: minmax(150px,1.9fr) 1.1fr 1.2fr 1fr 64px 82px; align-items:center; gap:8px; padding:6px 14px; border-bottom:1px solid #f0f1f4; font-size:11.5px; }
.pnn-row:last-child { border-bottom:none; }
.pnn-row .num { text-align:right; font-variant-numeric:tabular-nums; }
.pnn-head { background:#f7f8fa; font-size:10px; text-transform:uppercase; letter-spacing:.03em; color:#8a94a6; font-weight:700; }
.pnn-acct { white-space:nowrap; overflow:hidden; text-overflow:ellipsis; font-weight:600; }
.thead .mig-qual { font-weight: 700; text-transform: none; letter-spacing: 0; }

/* baseline card: bold-black value + prominent change vs beginning-of-year */
.k-primary { display: flex; align-items: baseline; gap: 9px; flex-wrap: wrap; margin-top: 4px; }
.k-primary .k-value { margin-top: 0; font-weight: 800; color: #1b1f27; }
.gchip { font-size: 16px; font-weight: 800; white-space: nowrap; }
.gchip.up { color: #1f9d55; }
.gchip.down { color: #c2410c; }
.gchip.na { color: #c0c5cf; font-weight: 700; }
.k-cap { font-size: 10px; color: #9aa0ac; margin-top: 1px; }
/* Old-offering comparison on the Bookings scope cards: share chip next to the value, grey
   context line under the sub-text, matching the grey band drawn in the sparkline. */
.ochip { font-size: 12px; font-weight: 700; color: #64748b; background: #eef1f5; border-radius: 999px; padding: 2px 7px; margin-left: 8px; vertical-align: 3px; white-space: nowrap; }
.k-old { display: flex; align-items: center; gap: 5px; font-size: 11px; color: #6b7383; margin-top: 4px; padding-top: 4px; border-top: 1px dashed #e2e6ec; }
.k-old b { color: #495260; font-weight: 700; }
.odot { width: 12px; height: 4px; border-radius: 2px; background: #94a3b8; flex: 0 0 auto; }
.base-2025 { margin-top: 4px; }
.spark-wrap { margin: 7px 0 3px; }
.spark { width: 100%; height: 38px; display: block; }
.spark-hit { cursor: crosshair; }
.spark-tip { position: fixed; z-index: 9999; background: #0d0d0f; color: #fff; font-size: 11px; font-weight: 500; line-height: 1.5; padding: 6px 9px; border-radius: 7px; box-shadow: 0 8px 24px rgba(0,0,0,.3); pointer-events: none; white-space: nowrap; display: none; }
.spark-axis { display: flex; justify-content: space-between; font-size: 8.5px; color: #b4bac6; padding: 0 2px; margin-top: -1px; font-variant-numeric: tabular-nums; }

/* ── hover info tooltip (budgetplaner pattern, pure CSS) ── */
.info { display:inline-flex; align-items:center; justify-content:center; width:15px; height:15px; border-radius:50%; background:#c9c9d2; color:#fff; font-size:10px; font-weight:800; font-style:normal; cursor:help; position:relative; vertical-align:middle; margin-left:5px; }
.info:hover { background:var(--accent); }
.info:hover::after { content:attr(data-tip); position:absolute; left:50%; top:22px; transform:translateX(-50%); background:#0d0d0f; color:#fff; font-size:11px; font-weight:500; line-height:1.55; width:270px; padding:10px 12px; border-radius:7px; box-shadow:0 8px 24px rgba(0,0,0,.3); z-index:50; text-transform:none; letter-spacing:0; white-space:pre-line; text-align:left; }
.info.tr:hover::after { left:auto; right:0; transform:none; }
.info.tl:hover::after { left:0; transform:none; }

/* ── collapsible methodik (native details) ── */
details.meth { margin-top:16px; border:1px solid #e6e8ec; border-radius:11px; background:#fbfbfd; }
details.meth > summary { list-style:none; cursor:pointer; padding:11px 15px; font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:.04em; color:#8a94a6; display:flex; align-items:center; gap:8px; }
details.meth > summary::-webkit-details-marker { display:none; }
details.meth > summary::before { content:'\25B8'; color:var(--accent); font-size:11px; }
details.meth[open] > summary::before { content:'\25BE'; }
details.meth .meth-body { padding:0 15px 13px; font-size:11.5px; color:#5b6169; line-height:1.65; }
details.meth .meth-body b { color:#1b1f27; }

/* ── card in data-validation state (greyed out) ── */
.kpi.validating { background:repeating-linear-gradient(135deg,#f5f6f8,#f5f6f8 10px,#f0f1f4 10px,#f0f1f4 20px); border-style:dashed; color:#9aa0ac; }
.kpi.validating .k-label { color:#9aa0ac; }
.kpi.validating .k-value { color:#b8bdc7; font-weight:800; font-size:24px; margin-top:4px; }
.kpi.validating .vld { font-size:10.5px; font-weight:700; color:#8a94a6; margin-top:6px; display:inline-flex; align-items:center; gap:5px; }
.kpi.validating .vld::before { content:'⏳'; }

