}
// Only accounts under real sales leadership (owner has a GTM motion AND a manager).
// Excludes pools / lead gen / admin owners without motion or without a TL.
function hasLeadership(x) { return x.motion !== NONE_MOTION && x.tl !== NONE_TL; }

/* ---------- data derivation ---------- */

function rawOpps() { return modelArray("opps"); }

// Accounts (active contract) that have an OPEN migration-potential opp.
function openMigrationAccountSet() {
  var s = {};
  rawOpps().forEach(function (o) { if (o && o.IsClosed === false && o.AccountId) s[o.AccountId] = true; });
  return s;
}

function segFor(migrated, isOpenMP, bookings, isPilot) {
  if (migrated) return isPilot ? "pilot" : "migrated";
  if (isOpenMP) return "inMigration";
  // Active contract but no revenue in the last 12 months = dormant / reactivation potential,
  // NOT counted as an active customer (definition: active contract AND bookings > 0).
  if (!(bookings > 0)) return "dormant";
  return (bookings >= QUALIFY_MIN) ? "openQualified" : "openSmall";
}
function currentAccounts() {
  var openMP = openMigrationAccountSet();
  var hp = highPrioIdSet();
  var pilots = pilotNcoAccountSet();
  var list = modelArray("accounts").map(function (r) {
    var migrated = r.New_Commercial_Offering__c === true;
    var of = ownerFields(r.Owner);
    var h = hp[r.Id];
    var bookings = r.Bookings_last_12_months__c || 0;
    return {
      id: r.Id,
      name: r.Name || "(ohne Name)",
      motion: of.motion,
      tl: of.tl,
      ic: of.ic,
      bookings: bookings,
      segment: segFor(migrated, !!openMP[r.Id], bookings, migrated && !!pilots[r.Id]),
      qualified: bookings >= QUALIFY_MIN,
      highPrio: !!h,
      hpEnd: h ? h.end : null,
      hpDays: h ? h.days : null,
      hpStatus: h ? h.status : null,
      hpKind: h ? h.kind : null
    };
  }).filter(hasLeadership);
  if (state.accExclAgency) list = list.filter(function (a) { return a.motion !== "Agency"; });
  if (state.accExclPilot) list = list.filter(function (a) { return a.segment !== "pilot"; });
  return list;
}

// High Priority = accounts with a HeyPaket ending within 3 months (query HighPriority).
function currentHighPrio() {
  var openMP = openMigrationAccountSet();
  var m = {};
  modelArray("highPrio").forEach(function (o) {
    var accId = o.AccountId; if (!accId) return;
    var acc = o.Account || {};
    var of = ownerFields(acc.Owner);
    if (!hasLeadership(of)) return;
    // A row is here because a HeyPaket is ending OR a won REACH contract is ending.
    // HeyPaket end = HeyPaket_End_Date__c; REACH end = the general Contract_End_Date__c.
    var kind, end, status;
    if (o.HeyPaket_End_Date__c && o.HeyPaket_Status__c && o.HeyPaket_Status__c !== "Inactive") {
      kind = "HeyPaket"; end = o.HeyPaket_End_Date__c; status = o.HeyPaket_Status__c;
    } else if (o.Product_Type__c === "REACH") {
      kind = "REACH"; end = o.Contract_End_Date__c; status = "Closed Won";
    } else return;
    if (!end) return;
    var ex = m[accId];
    // Keep the soonest-expiring contract per account (across HeyPaket + REACH).
    if (!ex || end < ex.end) {
      var migrated = acc.New_Commercial_Offering__c === true;
      var bookings = acc.Bookings_last_12_months__c || 0;
      m[accId] = {
        id: accId, name: acc.Name || "(ohne Account)",
        motion: of.motion, tl: of.tl, ic: of.ic, bookings: bookings,
        segment: segFor(migrated, !!openMP[accId], bookings),
        end: end, days: daysUntil(end), status: status, type: o.HeyPaket_Type__c, kind: kind
      };
    }
  });
  return Object.keys(m).map(function (k) { return m[k]; });
}
function highPrioIdSet() { var s = {}; currentHighPrio().forEach(function (a) { s[a.id] = a; }); return s; }

function currentOpps() {
  var activeSet = {};
  modelArray("accounts").forEach(function (a) { activeSet[a.Id] = true; });
  return rawOpps().map(function (o) {
    var acc = o.Account || {};
    var of = ownerFields(acc.Owner);
    var status = !o.IsClosed ? "open" : (o.IsWon ? "won" : "lost");
    return {
      id: o.Id,
      created: o.CreatedDate,
      account: acc.Name || "(ohne Account)",
      name: o.Name || "(ohne Name)",
      motion: of.motion,
      tl: of.tl,
      ic: of.ic,
      stage: o.StageName || "(ohne Stage)",
      status: status,
      segment: status,
      close: o.CloseDate,
      days: daysUntil(o.CloseDate),
      amount: o.Amount || 0,
      reach: o.Monthly_Reach_Budget__c,
      product: o.Product_Type__c,
      type: o.Contract_type__c,
      activity: o.LastActivityDate,
      lossCategory: o.Loss_Reason_Category__c,
      lossReason: o.plLossReason__c,
      lossDetail: o.Loss_Reason_Detail__c,
      accMigrated: acc.New_Commercial_Offering__c === true,
      inActive: !!activeSet[o.AccountId]
