  }).filter(hasLeadership);
}

/* ---------- generic tree ---------- */

// For account items (which carry a `qualified` flag) also track the qualified
// base and the migrated-among-qualified, so the tree can show a migration rate
// on qualified accounts (Bookings ≥ 6k) alongside the rate on all accounts.
function addQual(counts, it) {
  if (it.qualified === undefined) return;
  if (it.qualified) { counts.qual = (counts.qual || 0) + 1; if (it.segment === "migrated") counts.qualMig = (counts.qualMig || 0) + 1; }
}
function addBook(counts, it) {
  if (it.bookings === undefined) return;
  var b = it.bookings || 0;
  counts.book = (counts.book || 0) + b;
  if (it.qualified) counts.bookQual = (counts.bookQual || 0) + b;
  if (it.segment === "migrated") { counts.migBook = (counts.migBook || 0) + b; if (it.qualified) counts.migBookQual = (counts.migBookQual || 0) + b; }
}
function buildTree(items, keys, segs) {
  var root = { counts: emptyCounts(segs), children: {}, _order: [] };
  items.forEach(function (it) {
    addTo(root.counts, it.segment, it.amount || 0); addQual(root.counts, it); addBook(root.counts, it);
    var node = root;
    for (var i = 0; i < keys.length; i++) {
      var k = it[keys[i]];
      if (!node.children[k]) { node.children[k] = { label: k, counts: emptyCounts(segs), children: {}, _order: [], items: [] }; node._order.push(k); }
      node = node.children[k];
      addTo(node.counts, it.segment, it.amount || 0); addQual(node.counts, it); addBook(node.counts, it);
      if (i === keys.length - 1) node.items.push(it);
