    if (b.counts.total !== a.counts.total) return b.counts.total - a.counts.total;
    return String(a.label).localeCompare(String(b.label));
  });
}
function groupRow(label, level, path, counts, segs, hasChildren, rightHtml) {
  var open = !!state.expanded[path];
  var row = el("div", "row lvl" + level + (hasChildren ? " clickable" : ""));
  var nameCell = el("div", "name-cell"); nameCell.style.paddingLeft = (level * 18) + "px";
  nameCell.appendChild(el("span", "caret" + (open ? " open" : ""), hasChildren ? "▶" : ""));
  nameCell.appendChild(el("span", "name-txt", esc(label)));
  row.appendChild(nameCell);
  row.appendChild(el("div", "num count-big", String(counts.total)));
  var barCell = el("div", ""); var bw = el("div", "bar-wrap");
  bw.appendChild(stackedBar(counts, segs));
  bw.appendChild(el("div", "bar-legend", segLegend(counts, segs)));
  barCell.appendChild(bw); row.appendChild(barCell);
  row.appendChild(el("div", "mig-pct", rightHtml));
  if (hasChildren) row.addEventListener("click", function () { state.expanded[path] = !state.expanded[path]; render(); });
  return row;
}

/* ---------- Revenue: Neues Offering ---------- */

var MIG_COLOR = "#3b82f6", NEU_COLOR = "#f59e0b", OLD_COLOR = "#94a3b8";
// Share of the new offering in a scope: new / (new + old), both cumulative since rollout.
function shareChip(newAmt, oldAmt) {
