.rev-trend-hdr .trend-title { margin: 2px 0; }
.trend-wrap { border: 1px solid #e6e8ec; border-radius: 10px; padding: 8px 6px 2px; background: #fff; }
.trend-legend { display: flex; flex-wrap: wrap; gap: 10px 14px; margin: 10px 2px 16px; font-size: 11px; color: #4b5563; }
.trend-leg-item { display: inline-flex; align-items: center; gap: 5px; }
.trend-sw { width: 10px; height: 10px; border-radius: 2px; display: inline-block; }
.trend-note { font-size: 10.5px; color: #9aa0ac; padding: 0 2px 14px; line-height: 1.5; }

/* revenue block (Neues Offering) — budgetplaner magenta accent */
.rev-block { border: 1px solid #f3d9e8; background: #fdf7fb; border-radius: 12px; padding: 14px 14px 8px; margin-bottom: 18px; }
.rev-title { font-size: 13px; font-weight: 700; color: var(--accent-dark); margin: 2px 0 12px; }
.rev-title span { font-weight: 500; color: #8a94a6; font-size: 11px; }
.rev-row { display: grid; grid-template-columns: minmax(150px, 1.6fr) 1fr 1fr; align-items: center; padding: 8px 12px; border-bottom: 1px solid #f0f1f4; }
.rev-row:last-child { border-bottom: none; }
.rev-row .num { text-align: right; font-variant-numeric: tabular-nums; font-weight: 600; }
.rev-head { background: #f7f8fa; font-size: 10.5px; text-transform: uppercase; letter-spacing: 0.03em; color: #8a94a6; }
.rev-head .num { font-weight: 700; }
.rev-sub { color: #9aa0ac; font-weight: 400; font-size: 11px; }

