.ochip { font-size: 12px; font-weight: 700; color: #64748b; background: #eef1f5; border-radius: 999px; padding: 2px 7px; margin-left: 8px; vertical-align: 3px; white-space: nowrap; }
.k-old { display: flex; align-items: center; gap: 5px; font-size: 11px; color: #6b7383; margin-top: 4px; padding-top: 4px; border-top: 1px dashed #e2e6ec; }
