function groupLegendAmt(counts) { return segLegend(counts, PIPE_SEGMENTS) + '&nbsp;&nbsp;<span style="color:#b8bdc7">Σ ' + fmtEur(counts.amount) + "</span>"; }
function pipeGroupRow(label, level, path, counts, hasChildren) {
