/* ---------- shell ---------- */

function rerenderBody() {
  var body = document.getElementById("view-body"); if (!body) return;
  if (state.tab === "account") renderAccountBody(body, currentAccounts());
  else if (state.tab === "highprio") renderHighPrioBody(body, currentHighPrio());
  else renderPipelineBody(body, state.pipeScope === "active" ? currentOpps().filter(function (o) { return o.inActive; }) : currentOpps());
}
function render() {
  var root = document.getElementById("root"); if (!root) return;
  ensureSparkTip();
  root.innerHTML = "";
  var app = el("div", "app");
  var header = el("div", "header");
  header.appendChild(el("h1", "", "New Commercial Offering Dashboard"));
  header.appendChild(el("div", "sub", "Migrations-Pipeline & Success Tracking"));
  app.appendChild(header);

  var tabs = el("div", "tabs");
  [["account", "Account View"], ["pipeline", "Migrations-Pipeline"], ["highprio", "High Priority"], ["success", 'Success Guardrails']].forEach(function (t) {
    var tab = el("div", "tab" + (state.tab === t[0] ? " active" : ""), t[1]);
    tab.addEventListener("click", function () { state.tab = t[0]; state.search = ""; render(); });
    tabs.appendChild(tab);
  });
  app.appendChild(tabs);

  if (state.tab === "account") {
    var accounts = currentAccounts();
    if (!accounts.length) { var e = el("div", "empty"); e.innerHTML = "<h3>Noch keine Daten verbunden</h3><p>Erwartet <code>appsmith.model.accounts</code> aus <code>AccountMigration</code>.</p>"; app.appendChild(e); }
    else renderAccountView(app, accounts);
  } else if (state.tab === "highprio") {
    renderHighPriorityView(app);
  } else if (state.tab === "success") {
    renderSuccessView(app);
  } else {
    renderPipelineView(app, currentOpps());
  }
  root.appendChild(app);
}

if (window.appsmith && appsmith.onReady) {
  appsmith.onReady(function () { render(); });
  if (appsmith.onModelChange) appsmith.onModelChange(function () { render(); });
} else { render(); }
